-- Zonar multi-tenant foundation schema (Cloudflare D1 / SQLite)
-- This migration is intentionally not bound to or deployed against a live database.
-- IDs are generated by the application; tenant ownership is always resolved server-side.

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS tenants (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'suspended', 'closed')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  identity_issuer TEXT NOT NULL,
  identity_subject TEXT NOT NULL,
  email TEXT,
  display_name TEXT,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'disabled')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (identity_issuer, identity_subject)
);

CREATE TABLE IF NOT EXISTS memberships (
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  role TEXT NOT NULL
    CHECK (role IN ('tenant_owner', 'tenant_admin', 'analyst', 'operator', 'viewer')),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'revoked')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (tenant_id, user_id)
);

CREATE TABLE IF NOT EXISTS invitations (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
  email TEXT NOT NULL,
  role TEXT NOT NULL
    CHECK (role IN ('tenant_admin', 'analyst', 'operator', 'viewer')),
  token_hash TEXT NOT NULL UNIQUE,
  invited_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  expires_at TEXT NOT NULL,
  accepted_at TEXT,
  revoked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE IF NOT EXISTS tenant_files (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
  uploaded_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  original_filename TEXT NOT NULL,
  object_key TEXT NOT NULL UNIQUE,
  content_type TEXT NOT NULL,
  byte_size INTEGER NOT NULL CHECK (byte_size >= 0),
  sha256_hex TEXT,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'received'
    CHECK (status IN ('received', 'processing', 'processed', 'failed', 'quarantined', 'deletion_pending', 'deleted')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);

CREATE TABLE IF NOT EXISTS processing_jobs (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
  file_id TEXT NOT NULL REFERENCES tenant_files(id) ON DELETE RESTRICT,
  requested_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  processor_version TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled')),
  result_object_key TEXT UNIQUE,
  error_code TEXT,
  started_at TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Audit rows are append-only at the database layer. Do not cascade-delete them.
CREATE TABLE IF NOT EXISTS audit_events (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
  actor_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT,
  event_type TEXT NOT NULL,
  resource_type TEXT,
  resource_id TEXT,
  request_id TEXT,
  outcome TEXT NOT NULL CHECK (outcome IN ('success', 'denied', 'failure')),
  details_json TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX IF NOT EXISTS idx_memberships_user_status
  ON memberships(user_id, status);
CREATE INDEX IF NOT EXISTS idx_invitations_tenant_email
  ON invitations(tenant_id, email);
CREATE INDEX IF NOT EXISTS idx_invitations_expiry
  ON invitations(expires_at);
CREATE INDEX IF NOT EXISTS idx_tenant_files_tenant_created
  ON tenant_files(tenant_id, created_at);
CREATE INDEX IF NOT EXISTS idx_tenant_files_tenant_status
  ON tenant_files(tenant_id, status);
CREATE INDEX IF NOT EXISTS idx_processing_jobs_tenant_created
  ON processing_jobs(tenant_id, created_at);
CREATE INDEX IF NOT EXISTS idx_processing_jobs_file
  ON processing_jobs(file_id);
CREATE INDEX IF NOT EXISTS idx_audit_events_tenant_created
  ON audit_events(tenant_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_events_actor_created
  ON audit_events(actor_user_id, created_at);


-- An actor recorded on a tenant event must have an active membership in that tenant.
CREATE TRIGGER IF NOT EXISTS trg_audit_actor_tenant_membership
BEFORE INSERT ON audit_events
WHEN NEW.actor_user_id IS NOT NULL
 AND NOT EXISTS (
   SELECT 1 FROM memberships m
   INNER JOIN users u ON u.id = m.user_id
   INNER JOIN tenants t ON t.id = m.tenant_id
   WHERE m.tenant_id = NEW.tenant_id
     AND m.user_id = NEW.actor_user_id
     AND m.status = 'active'
     AND u.status = 'active'
     AND t.status = 'active'
 )
BEGIN
  SELECT RAISE(ABORT, 'audit actor must have active membership in tenant');
END;

-- Prevent ordinary application SQL from altering or deleting audit history.
CREATE TRIGGER IF NOT EXISTS trg_audit_events_no_update
BEFORE UPDATE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit events are immutable');
END;

CREATE TRIGGER IF NOT EXISTS trg_audit_events_no_delete
BEFORE DELETE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit events are immutable');
END;


CREATE TRIGGER IF NOT EXISTS trg_audit_actor_tenant_membership
BEFORE INSERT ON audit_events
WHEN NEW.actor_user_id IS NOT NULL
 AND NOT EXISTS (
   SELECT 1 FROM memberships m
   INNER JOIN users u ON u.id = m.user_id
   INNER JOIN tenants t ON t.id = m.tenant_id
   WHERE m.tenant_id = NEW.tenant_id
     AND m.user_id = NEW.actor_user_id
     AND m.status = 'active'
     AND u.status = 'active'
     AND t.status = 'active'
 )
BEGIN
  SELECT RAISE(ABORT, 'audit actor must have active membership in tenant');
END;

CREATE TRIGGER IF NOT EXISTS trg_audit_events_no_update
BEFORE UPDATE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit events are immutable');
END;

CREATE TRIGGER IF NOT EXISTS trg_audit_events_no_delete
BEFORE DELETE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit events are immutable');
END;
